    color: "Phantom Black",
    price: 199.99,
    quantity: 1,
    image: "https://bundui-images.netlify.app/products/04.jpeg"
  },
  {
    id: "5",
    name: "JLab Epic Air Sport ANC True Wireless Earbuds",
    color: "Black",
    price: 99.99,
    quantity: 1,
    image: "https://bundui-images.netlify.app/products/06.jpeg"
  }
];

export type CartItemType = (typeof cartData)[number];

export default function Cart() {
  const [cartItems, setCartItems] = useState<CartItemType[]>(cartData);

  const updateQuantity = (id: string, quantity: number) => {
    setCartItems((items) => items.map((item) => (item.id === id ? { ...item, quantity } : item)));
  };

  const removeItem = (id: string) => {
    setCartItems((items) => items.filter((item) => item.id !== id));
  };

  const handleApplyCoupon = (code: string) => {
    console.log("Applying coupon:", code);
    // Implement coupon logic here
  };

  const subtotal = cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const discount = 0;
  const delivery = 29.99;
  const tax = 39.99;

  return (
    <div className="bg-background min-h-screen p-4 lg:p-8">
      <div className="mx-auto max-w-7xl">
        {/* Main Content Grid */}
        <div className="grid grid-cols-1 gap-8 lg:grid-cols-3">
          {/* Shopping Cart Section */}
          <div className="lg:col-span-2">
            <div className="bg-card border-cart-border rounded-lg border p-6">
              <h1 className="mb-6 text-2xl font-semibold">Shopping Cart</h1>

              {/* Table Header - Hidden on mobile */}
              <div className="border-cart-border text-muted-foreground mb-4 hidden gap-4 border-b pb-4 text-sm font-medium lg:grid lg:grid-cols-[2fr,1fr,1fr,auto]">
                <div>Product</div>
                <div className="text-center">Quantity</div>
                <div className="text-center">Price</div>
                <div className="w-8"></div>
              </div>

              {/* Cart Items */}
              <div className="space-y-4">
                {cartItems.map((item) => (
                  <CartItem
                    key={item.id}
                    {...item}
                    onUpdateQuantity={updateQuantity}
                    onRemove={removeItem}
                  />
                ))}
              </div>
            </div>

            {/* Action Buttons */}
            <div className="mt-6 flex flex-col gap-4 sm:flex-row">
              <Button variant="outline" className="flex items-center gap-2">
                <ArrowLeft className="h-4 w-4" />
                Back
              </Button>
              <Button variant="destructive" className="bg-destructive hover:bg-destructive/90">
                Cancel Order
              </Button>
            </div>
          </div>

          {/* Right Sidebar */}
          <div className="space-y-6">
            <CouponSection onApplyCoupon={handleApplyCoupon} />
            <OrderSummary subtotal={subtotal} discount={discount} delivery={delivery} tax={tax} />
            <PaymentMethods />
          </div>
        </div>
      </div>
    </div>
  );
}

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useState } from "react";

interface CouponSectionProps {
  onApplyCoupon: (code: string) => void;
}

export const CouponSection = ({ onApplyCoupon }: CouponSectionProps) => {
  const [couponCode, setCouponCode] = useState("");

  const handleApply = () => {
    if (couponCode.trim()) {
      onApplyCoupon(couponCode.trim());
    }
  };

  return (
    <div className="bg-card border-cart-border rounded-lg border p-6">
      <h2 className="mb-4 text-xl font-semibold">Coupon Code</h2>
      <div className="space-y-4">
        <Input
          placeholder="Enter Your Coupon Code"
          value={couponCode}
          onChange={(e) => setCouponCode(e.target.value)}
          className="h-12"
        />
        <Button onClick={handleApply} className="bg-primary hover:bg-primary/90 h-12 w-full">
          Apply Your Coupon
        </Button>
      </div>
    </div>
  );
};

interface OrderSummaryProps {
  subtotal: number;
  discount: number;
  delivery: number;
  tax: number;
}

export const OrderSummary = ({ subtotal, discount, delivery, tax }: OrderSummaryProps) => {
  const total = subtotal - discount + delivery + tax;

  return (
    <div className="bg-card border-cart-border rounded-lg border p-6">
      <h2 className="mb-6 text-xl font-semibold">Order Summary</h2>

      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <span className="text-muted-foreground">Discount</span>
          <span className="font-medium">${discount.toFixed(2)}</span>
        </div>

        <div className="flex items-center justify-between">
          <span className="text-muted-foreground">Delivery</span>
          <span className="font-medium">${delivery.toFixed(2)}</span>
        </div>

        <div className="flex items-center justify-between">
          <span className="text-muted-foreground">Tax</span>
          <span className="font-medium">${tax.toFixed(2)}</span>
        </div>

        <hr className="border-cart-border" />

        <div className="flex items-center justify-between">
          <span className="text-lg font-semibold">Total</span>
          <span className="text-xl font-bold">${total.toFixed(2)}</span>
        </div>
      </div>
    </div>
  );
};

import { Button } from "@/components/ui/button";

export const PaymentMethods = () => {
  const paymentMethods = [
    { id: "paypal", name: "PayPal", icon: "💳" },
    { id: "stripe", name: "Stripe", icon: "$" },
    { id: "mastercard", name: "Mastercard", icon: "💳" },
    { id: "bitcoin", name: "Bitcoin", icon: "₿" }
  ];

  return (
    <div className="bg-card border-cart-border rounded-lg border p-6">
      <h2 className="mb-6 text-xl font-semibold">Payment Method</h2>

      <div className="mb-6 grid grid-cols-4 gap-3">
        {paymentMethods.map((method) => (
          <Button
            key={method.id}
            variant="outline"
            className="hover:bg-primary hover:text-primary-foreground hover:border-primary aspect-square h-12 p-0">
            <span className="text-lg">{method.icon}</span>
          </Button>
        ))}
      </div>

      <Button className="bg-primary hover:bg-primary/90 text-primary-foreground h-12 w-full">
        Check Out
      </Button>
    </div>
  );
};

import Cart from "./components/cart";

export default function Page() {
  return <Cart />;
}

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "cursor-pointer inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground shadow-xs hover:bg-primary/90",
        destructive:
          "bg-destructive text-white shadow-xs hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
        secondary: "bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline"
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9"
      }
    },
    defaultVariants: {
      variant: "default",
      size: "default"
    }
  }
);

function Button({
  className,
  variant,
  size,
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
  }) {
  const Comp = asChild ? Slot : "button";

  return (
    <Comp
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

export { Button, buttonVariants };

import * as React from "react"

